-- Migração 032: Criação da tabela de Obras Culturais, preenchimento de idiomas nativos e catalogação de obras

CREATE TABLE IF NOT EXISTS obras_culturais (
    id TEXT PRIMARY KEY,
    pessoa_id TEXT NOT NULL REFERENCES pessoas(id) ON DELETE CASCADE,
    categoria TEXT NOT NULL CHECK(categoria IN ('livro', 'musica', 'teatro', 'pesquisa', 'arte', 'outro')),
    titulo TEXT NOT NULL,
    subtipo TEXT,
    ano INTEGER,
    ano_fim INTEGER,
    detalhes TEXT,
    local_id TEXT REFERENCES locais(id) ON DELETE SET NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_obras_culturais_pessoa ON obras_culturais(pessoa_id);
CREATE INDEX IF NOT EXISTS idx_obras_culturais_categoria ON obras_culturais(categoria);

-- 1. Preenchimento de idiomas nativos para figuras públicas com base no local de nascimento
SELECT 'idm_nat_' || p.id, p.id,
  CASE l.pais_id
    WHEN 'br' THEN 'Português'
    WHEN 'pt' THEN 'Português'
    WHEN 'us' THEN 'Inglês'
    WHEN 'gb' THEN 'Inglês'
    WHEN 'fr' THEN 'Francês'
    WHEN 'de' THEN 'Alemão'
    WHEN 'at' THEN 'Alemão'
    WHEN 'it' THEN 'Italiano'
    WHEN 'es' THEN 'Espanhol'
    WHEN 'ar' THEN 'Espanhol'
    WHEN 'ru' THEN 'Russo'
    WHEN 'cn' THEN 'Chinês (Mandarim / Clássico)'
    WHEN 'jp' THEN 'Japonês'
    WHEN 'dk' THEN 'Dinamarquês'
    WHEN 'se' THEN 'Sueco'
    WHEN 'gr' THEN 'Grego'
    WHEN 'ge' THEN 'Georgiano'
    WHEN 'eg' THEN 'Egípcio antigo'
    WHEN 'il' THEN 'Hebraico bíblico'
    WHEN 'ps' THEN 'Hebraico bíblico'
    WHEN 'iq' THEN 'Hebraico antigo / Aramaico'
    ELSE 'Português'
  END
FROM pessoas p
JOIN eventos e ON e.pessoa_id = p.id AND e.tipo_evento = 'nascimento'
JOIN locais l ON e.local_id = l.id
WHERE p.is_publico = 1
  AND p.id NOT IN (SELECT pessoa_id FROM idiomas_pessoa)
ON CONFLICT(id) DO NOTHING;

